/*==============================================================
  CineChef - Fase 3c: recetas, tanda 2 de 4
  25 recetas nuevas; no modifica la tanda 1.
  Solo utiliza ingredientes cargados en 03b_ingredients.sql.
==============================================================*/
USE CineChefDB;
GO

INSERT INTO dbo.Recipes (Name, Description, PrepMin, Difficulty, Servings)
SELECT source.Name, source.Description, source.PrepMin, source.Difficulty, source.Servings
FROM (VALUES
(N'Rustic Sausage and Cabbage Skillet', N'This rustic skillet brings the easy comfort of a country kitchen, with browned sausage, sweet cabbage, potato, onion, and thyme sharing one warm pan. It is savory, simple, and satisfying, made for a chilly evening when dinner should feel hearty without demanding ceremony.', 45, 1, 4),
(N'Green Bean Almond Salad', N'Crisp green beans, toasted almonds, lemon, parsley, and olive oil make a salad that feels bright and composed. It has the freshness of a garden lunch and enough nutty richness to linger, perfect for a sunny table when a meal should be light but never forgettable.', 25, 1, 4),
(N'Velvet Cauliflower Soup', N'Cauliflower, leek, potato, cream, and thyme melt into a pale, velvety soup with a delicate sweetness. The bowl feels calm and restorative, like a quiet pause after a crowded day, while black pepper and toasted bread add just enough warmth and texture.', 50, 1, 4),
(N'Paprika Turkey Meatballs', N'Tender turkey meatballs carry paprika, garlic, onion, parsley, and a gentle tomato sauce. Their familiar fragrance makes the kitchen feel welcoming, while the soft texture and warm spice create a relaxed supper for a family table or a low-key evening with friends.', 50, 2, 4),
(N'Roasted Salmon with Asparagus', N'Salmon and asparagus roast together with lemon, olive oil, garlic, and black pepper, creating a clean, springlike plate. The fish is rich but the mood stays light, making this an elegant choice for a hopeful evening when bright flavors and little effort are both welcome.', 35, 1, 4),
(N'Warm Potato Leek Gratin', N'Thin potatoes and sweet leek bake beneath milk, butter, cream, and Parmesan until the edges turn golden. This is soft, fragrant comfort for long nights, with a homely richness that invites small portions, second helpings, and the feeling of being looked after.', 80, 2, 6),
(N'Tropical Pineapple Fried Rice', N'Rice, pineapple, peas, carrot, tofu, soy sauce, and lime create a playful bowl of sweet, salty, and tangy flavors. It feels like a quick holiday in the middle of the week, colorful and energetic enough to turn an ordinary dinner into a cheerful occasion.', 35, 2, 4),
(N'Beef Steak with Chimichurri Mood', N'A seared beef steak meets parsley, garlic, lemon, olive oil, and black pepper in a vivid sauce that tastes fresh and confident. The dish feels celebratory without being formal, suited to an evening when appetite is bold and the table deserves something wonderfully direct.', 30, 2, 2),
(N'Creamy Pea and Ham Soup', N'Sweet peas, ham, onion, potato, and cream make a bowl with a soft green color and a reassuringly familiar flavor. It is gentle, savory, and quietly nostalgic, the sort of soup that makes a hurried lunch slow down and gives a gray afternoon a little kindness.', 45, 1, 4),
(N'Baked Eggplant Parmesan', N'Tender eggplant, tomato, mozzarella, Parmesan, basil, and breadcrumbs bake into a bubbling casserole with a crisp golden top. It feels generous and theatrical when it reaches the table, yet the soft layers remain deeply comforting, ideal for a relaxed shared dinner.', 75, 2, 6),
(N'Chicken and Vegetable Couscous', N'Chicken, couscous, carrot, zucchini, chickpeas, cumin, and parsley create a fragrant bowl with gentle North African warmth. The grains stay fluffy and the vegetables bring color, making the meal feel generous, sunny, and welcoming on a night meant for lingering.', 55, 2, 4),
(N'Tuna Avocado Rice Bowl', N'Tuna, rice, avocado, cucumber, sesame, lime, and soy sauce form a cool, balanced bowl with clean seaside freshness. It is quick enough for a busy evening but colorful enough to feel cared for, a bright meal for restoring energy without unnecessary heaviness.', 25, 1, 2),
(N'Carrot Ginger Coconut Soup', N'Sweet carrot, coconut milk, lime, ginger-like chili warmth, and cumin create a glowing soup with a gentle tropical note. Its smooth texture is soothing, while the citrus keeps it awake. Serve it when comfort is needed but the mood still wants color and movement.', 40, 1, 4),
(N'Bacon Spinach Potato Hash', N'Crisp bacon, potato, spinach, onion, garlic, and eggs turn a simple hash into a warm weekend ritual. It is savory and satisfying, with soft yolk and browned edges bringing a little drama to the plate. Perfect for a late breakfast shared without a schedule.', 40, 1, 4),
(N'Lamb and Eggplant Tomato Stew', N'Lamb, eggplant, tomato, onion, garlic, oregano, and cinnamon simmer into a fragrant stew with deep Mediterranean character. The flavors become rounded and tender with time, creating a patient dinner for cool evenings, soft music, and generous pieces of bread.', 90, 3, 6),
(N'Berry Yogurt Breakfast Bowl', N'Yogurt, strawberries, blueberries, raspberries, banana, honey, and oats make a fresh breakfast that feels like morning sunlight. The fruit is lively, the yogurt is creamy, and the oats add comfort, giving a bright start to days that need a little optimism.', 10, 1, 2),
(N'Sweet Potato Black Bean Bowl', N'Roasted sweet potato, black beans, corn, avocado, lime, chili, and quinoa create a colorful bowl with smoky warmth and creamy contrast. It feels nourishing rather than austere, a cheerful supper for resetting after a long day while keeping the table lively.', 45, 1, 4),
(N'Rosemary Beef and Mushroom Pie', N'Beef, mushrooms, onion, carrot, rosemary, and a golden wheat flour crust make a pie with deep, savory comfort. Steam rises when it is cut, bringing the atmosphere of a winter kitchen and the slow satisfaction of a meal prepared for people worth gathering around.', 110, 3, 6),
(N'Cucumber Melon Lime Salad', N'Cucumber, melon-like sweetness from pear, lime, mint-like parsley, and feta make a crisp salad with a cool, refreshing personality. It feels like an afternoon on a shaded terrace, clean and delicate enough for hot weather yet interesting enough to hold attention.', 15, 1, 4),
(N'Spicy Tuna Tomato Toasts', N'Bread, tuna, tomato, mayonnaise, mustard, red chili, lemon, and parsley create quick toasts with creamy, sharp, and lively flavors. They are casual but satisfying, the kind of snack that turns a quiet film night into a small feast without much preparation.', 20, 1, 4),
(N'Vegetable Coconut Noodle Soup', N'Noodles, coconut milk, mushrooms, broccoli, carrot, lime, curry powder, and tofu make a fragrant soup with gentle heat. It feels restorative and colorful, ideal for evenings when the body wants warmth and the mind wants a meal that tastes like somewhere far away.', 45, 2, 4),
(N'Honey Mustard Pork Medallions', N'Tender pork, mustard, honey, apple, thyme, and black pepper create a glossy sweet-savory plate with autumn warmth. The sauce is bright rather than heavy, and the fruit softens beside the meat, making this an easy centerpiece for a calm, candlelit dinner.', 45, 2, 4),
(N'Cheesy Broccoli Rice Bake', N'Broccoli, rice, cheddar, milk, eggs, onion, and breadcrumbs bake into a golden casserole with a soft center. It is familiar, cheerful, and deeply practical, a comforting family dish for evenings when everyone wants something warm, filling, and easy to share.', 60, 1, 6),
(N'Mango Strawberry Fruit Cups', N'Mango, strawberries, orange, lime, coconut, and honey make a bright fruit dessert that tastes like a small festival. Juicy textures and citrus fragrance keep it refreshing, while coconut adds softness. Serve it after a lively meal when the ending should feel sunny.', 15, 1, 4),
(N'Garlic Mussel Tomato Pot', N'Mussels steam with tomato, garlic, onion, white-wine-like vinegar, parsley, and chili in a lively pot that smells of the coast. The broth is bright and briny, the mood is convivial, and warm bread turns the whole dish into an unhurried communal experience.', 35, 2, 4)
) AS source (Name, Description, PrepMin, Difficulty, Servings)
WHERE NOT EXISTS (SELECT 1 FROM dbo.Recipes AS target WHERE target.Name = source.Name);
GO

