(N'Garlic Mussel Tomato Pot',N'Mussels',700.00,N'g'),(N'Garlic Mussel Tomato Pot',N'Tomato',400.00,N'g'),(N'Garlic Mussel Tomato Pot',N'Garlic',3.00,N'cloves'),(N'Garlic Mussel Tomato Pot',N'Onion',1.00,N'unit'),(N'Garlic Mussel Tomato Pot',N'Bread',4.00,N'slices')
) AS source (RecipeName, IngredientName, Quantity, Unit)
JOIN dbo.Recipes AS recipe ON recipe.Name = source.RecipeName
JOIN dbo.Ingredients AS ingredient ON ingredient.Name = source.IngredientName
WHERE NOT EXISTS (
    SELECT 1 FROM dbo.RecipeIngredients AS target
    WHERE target.RecipeId = recipe.RecipeId AND target.IngredientId = ingredient.IngredientId
);
GO

SELECT N'Recipes' AS Catalog, COUNT(*) AS ItemCount,
       MIN(LEN(Description)) AS MinDescriptionLength,
       MAX(LEN(Description)) AS MaxDescriptionLength
FROM dbo.Recipes
WHERE Name IN (
N'Rustic Sausage and Cabbage Skillet',N'Green Bean Almond Salad',N'Velvet Cauliflower Soup',N'Paprika Turkey Meatballs',N'Roasted Salmon with Asparagus',N'Warm Potato Leek Gratin',N'Tropical Pineapple Fried Rice',N'Beef Steak with Chimichurri Mood',N'Creamy Pea and Ham Soup',N'Baked Eggplant Parmesan',N'Chicken and Vegetable Couscous',N'Tuna Avocado Rice Bowl',N'Carrot Ginger Coconut Soup',N'Bacon Spinach Potato Hash',N'Lamb and Eggplant Tomato Stew',N'Berry Yogurt Breakfast Bowl',N'Sweet Potato Black Bean Bowl',N'Rosemary Beef and Mushroom Pie',N'Cucumber Melon Lime Salad',N'Spicy Tuna Tomato Toasts',N'Vegetable Coconut Noodle Soup',N'Honey Mustard Pork Medallions',N'Cheesy Broccoli Rice Bake',N'Mango Strawberry Fruit Cups',N'Garlic Mussel Tomato Pot');
SELECT N'RecipeIngredients' AS Catalog, COUNT(*) AS ItemCount
FROM dbo.RecipeIngredients AS ri JOIN dbo.Recipes AS r ON r.RecipeId = ri.RecipeId
WHERE r.Name IN (N'Rustic Sausage and Cabbage Skillet',N'Green Bean Almond Salad',N'Velvet Cauliflower Soup',N'Paprika Turkey Meatballs',N'Roasted Salmon with Asparagus',N'Warm Potato Leek Gratin',N'Tropical Pineapple Fried Rice',N'Beef Steak with Chimichurri Mood',N'Creamy Pea and Ham Soup',N'Baked Eggplant Parmesan',N'Chicken and Vegetable Couscous',N'Tuna Avocado Rice Bowl',N'Carrot Ginger Coconut Soup',N'Bacon Spinach Potato Hash',N'Lamb and Eggplant Tomato Stew',N'Berry Yogurt Breakfast Bowl',N'Sweet Potato Black Bean Bowl',N'Rosemary Beef and Mushroom Pie',N'Cucumber Melon Lime Salad',N'Spicy Tuna Tomato Toasts',N'Vegetable Coconut Noodle Soup',N'Honey Mustard Pork Medallions',N'Cheesy Broccoli Rice Bake',N'Mango Strawberry Fruit Cups',N'Garlic Mussel Tomato Pot');
GO
